using System;
class XLadderClearanceChecks{static void Main(){var s=NavalShipDefinition.Dreadnought;var path=NavalTurretAccessLayout.Entry(s,3);var bottom=path[0];var middle=path[1];var top=path[2];if(Math.Abs(bottom.x-middle.x)>.00001f||Math.Abs(bottom.x-top.x)>.00001f)throw new Exception("Ladder axis differs across levels");if(NavalTurretAccessLayout.XLadderOut<.8f+.8f/s.Scale)throw new Exception("Ladder body overlaps barbette foundation");if(Math.Abs(bottom.y-s.WeatherDeck)>.001f)throw new Exception("Bottom must meet deck");Console.WriteLine("PASS: X ladder stays outside foundation with full crew capsule clearance and aligned endpoints.");}}
